-- Wayfarer Phase 4: immutable receipt evidence, personal projections, and versioned achievements.
CREATE TABLE `ArtifactGrantReceipt` (`id` VARCHAR(191) NOT NULL, `sessionId` VARCHAR(191) NOT NULL, `sourceEventId` VARCHAR(191) NOT NULL, `grantId` VARCHAR(191) NOT NULL, `schemaVersion` INTEGER NOT NULL DEFAULT 1, `artifactDefinitionId` VARCHAR(191) NOT NULL, `artifactOccurrenceId` VARCHAR(191) NOT NULL, `publishedVersionId` VARCHAR(191) NOT NULL, `sourceBlockId` VARCHAR(191) NULL, `recipientPolicy` VARCHAR(191) NOT NULL, `resolvedRecipientMembershipIds` LONGTEXT NOT NULL, `resolvedRecipientProfileIds` LONGTEXT NOT NULL, `discoveringMembershipId` VARCHAR(191) NULL, `requiredCrewRole` VARCHAR(191) NULL, `sharedInventoryAction` VARCHAR(191) NOT NULL, `personalGrantState` VARCHAR(191) NOT NULL, `custodyKind` VARCHAR(191) NOT NULL, `assemblyDefinitionId` VARCHAR(191) NULL, `componentRole` VARCHAR(191) NULL, `receiptState` VARCHAR(191) NOT NULL DEFAULT 'ACTIVE', `occurredAt` DATETIME(3) NOT NULL, `correctionOfGrantId` VARCHAR(191) NULL, `correctionReason` TEXT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `ArtifactGrantReceipt_sourceEventId_key` (`sourceEventId`), UNIQUE KEY `ArtifactGrantReceipt_grantId_key` (`grantId`), KEY `ArtifactGrantReceipt_sessionId_occurredAt_idx` (`sessionId`,`occurredAt`), KEY `ArtifactGrantReceipt_publishedVersionId_artifactDefinitionId_idx` (`publishedVersionId`,`artifactDefinitionId`), CONSTRAINT `ArtifactGrantReceipt_sessionId_fkey` FOREIGN KEY (`sessionId`) REFERENCES `TaleSession`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `PlayerArtifactRecord` (`id` VARCHAR(191) NOT NULL, `playerProfileId` VARCHAR(191) NOT NULL, `sourcePlaythroughId` VARCHAR(191) NOT NULL, `sourceGrantEventId` VARCHAR(191) NOT NULL, `sourceGrantSequence` INTEGER NOT NULL, `sourceBlockId` VARCHAR(191) NULL, `publishedVersionId` VARCHAR(191) NOT NULL, `publishedVersionChecksum` VARCHAR(191) NOT NULL, `chronicleTitleSnapshot` VARCHAR(191) NOT NULL, `artifactDefinitionId` VARCHAR(191) NOT NULL, `artifactNameSnapshot` VARCHAR(191) NOT NULL, `artifactTypeSnapshot` VARCHAR(191) NOT NULL DEFAULT 'ARTIFACT', `representationSnapshot` VARCHAR(191) NOT NULL DEFAULT 'FALLBACK', `collectionKeySnapshot` VARCHAR(191) NULL, `assemblyKeySnapshot` VARCHAR(191) NULL, `componentRoleSnapshot` VARCHAR(191) NULL, `recipientPolicy` VARCHAR(191) NOT NULL, `recipientEvidence` LONGTEXT NOT NULL, `ownershipState` VARCHAR(191) NOT NULL, `custody` VARCHAR(191) NOT NULL DEFAULT 'PERSONAL', `recordStatus` VARCHAR(191) NOT NULL DEFAULT 'ACTIVE', `discoveredAt` DATETIME(3) NULL, `grantedAt` DATETIME(3) NULL, `witnessedAt` DATETIME(3) NULL, `revokedAt` DATETIME(3) NULL, `archivedAt` DATETIME(3) NULL, `correctedAt` DATETIME(3) NULL, `correctionReason` TEXT NULL, `sourceFingerprint` VARCHAR(191) NOT NULL, `lastDerivedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `PlayerArtifactRecord_playerProfileId_sourceGrantEventId_key` (`playerProfileId`,`sourceGrantEventId`), KEY `PlayerArtifactRecord_playerProfileId_recordStatus_grantedAt_idx` (`playerProfileId`,`recordStatus`,`grantedAt`), KEY `PlayerArtifactRecord_playerProfileId_ownershipState_artifactDefinitionId_idx` (`playerProfileId`,`ownershipState`,`artifactDefinitionId`), KEY `PlayerArtifactRecord_sourcePlaythroughId_sourceGrantSequence_idx` (`sourcePlaythroughId`,`sourceGrantSequence`), CONSTRAINT `PlayerArtifactRecord_playerProfileId_fkey` FOREIGN KEY (`playerProfileId`) REFERENCES `PlayerProfile`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `PlayerArtifactRecord_publishedVersionId_fkey` FOREIGN KEY (`publishedVersionId`) REFERENCES `PublishedTaleVersion`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `PlayerArtifactPersonalization` (`id` VARCHAR(191) NOT NULL, `artifactRecordId` VARCHAR(191) NOT NULL, `favorite` BOOLEAN NOT NULL DEFAULT false, `privateNote` TEXT NULL, `chronicleMemoryId` VARCHAR(191) NULL, `visibility` VARCHAR(191) NOT NULL DEFAULT 'ONLY_ME', `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `PlayerArtifactPersonalization_artifactRecordId_key` (`artifactRecordId`), CONSTRAINT `PlayerArtifactPersonalization_artifactRecordId_fkey` FOREIGN KEY (`artifactRecordId`) REFERENCES `PlayerArtifactRecord`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ArtifactDisplayCase` (`id` VARCHAR(191) NOT NULL, `playerProfileId` VARCHAR(191) NOT NULL, `name` VARCHAR(191) NOT NULL, `description` TEXT NULL, `visibility` VARCHAR(191) NOT NULL DEFAULT 'ONLY_ME', `unlistedToken` VARCHAR(191) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `ArtifactDisplayCase_unlistedToken_key` (`unlistedToken`), UNIQUE KEY `ArtifactDisplayCase_playerProfileId_name_key` (`playerProfileId`,`name`), KEY `ArtifactDisplayCase_playerProfileId_visibility_idx` (`playerProfileId`,`visibility`), CONSTRAINT `ArtifactDisplayCase_playerProfileId_fkey` FOREIGN KEY (`playerProfileId`) REFERENCES `PlayerProfile`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ArtifactDisplayItem` (`id` VARCHAR(191) NOT NULL, `displayCaseId` VARCHAR(191) NOT NULL, `artifactRecordId` VARCHAR(191) NOT NULL, `position` INTEGER NOT NULL DEFAULT 0, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `ArtifactDisplayItem_displayCaseId_artifactRecordId_key` (`displayCaseId`,`artifactRecordId`), UNIQUE KEY `ArtifactDisplayItem_displayCaseId_position_key` (`displayCaseId`,`position`), KEY `ArtifactDisplayItem_artifactRecordId_idx` (`artifactRecordId`), CONSTRAINT `ArtifactDisplayItem_displayCaseId_fkey` FOREIGN KEY (`displayCaseId`) REFERENCES `ArtifactDisplayCase`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `ArtifactDisplayItem_artifactRecordId_fkey` FOREIGN KEY (`artifactRecordId`) REFERENCES `PlayerArtifactRecord`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `PlayerArtifactAssembly` (`id` VARCHAR(191) NOT NULL, `playerProfileId` VARCHAR(191) NOT NULL, `publishedVersionId` VARCHAR(191) NOT NULL, `sourcePlaythroughId` VARCHAR(191) NOT NULL, `assemblyKeySnapshot` VARCHAR(191) NOT NULL, `assembledArtifactName` VARCHAR(191) NOT NULL, `recipeSnapshot` LONGTEXT NOT NULL, `status` VARCHAR(191) NOT NULL DEFAULT 'IN_PROGRESS', `completedAt` DATETIME(3) NULL, `sourceFingerprint` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `PlayerArtifactAssembly_playerProfileId_sourcePlaythroughId_assemblyKeySnapshot_key` (`playerProfileId`,`sourcePlaythroughId`,`assemblyKeySnapshot`), KEY `PlayerArtifactAssembly_playerProfileId_status_completedAt_idx` (`playerProfileId`,`status`,`completedAt`), CONSTRAINT `PlayerArtifactAssembly_playerProfileId_fkey` FOREIGN KEY (`playerProfileId`) REFERENCES `PlayerProfile`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `PlayerArtifactAssembly_publishedVersionId_fkey` FOREIGN KEY (`publishedVersionId`) REFERENCES `PublishedTaleVersion`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `PlayerArtifactContribution` (`id` VARCHAR(191) NOT NULL, `assemblyId` VARCHAR(191) NOT NULL, `artifactRecordId` VARCHAR(191) NOT NULL, `componentKey` VARCHAR(191) NOT NULL, `componentRole` VARCHAR(191) NULL, `state` VARCHAR(191) NOT NULL DEFAULT 'ACTIVE', `contributedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `PlayerArtifactContribution_assemblyId_artifactRecordId_key` (`assemblyId`,`artifactRecordId`), KEY `PlayerArtifactContribution_artifactRecordId_state_idx` (`artifactRecordId`,`state`), CONSTRAINT `PlayerArtifactContribution_assemblyId_fkey` FOREIGN KEY (`assemblyId`) REFERENCES `PlayerArtifactAssembly`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `PlayerArtifactContribution_artifactRecordId_fkey` FOREIGN KEY (`artifactRecordId`) REFERENCES `PlayerArtifactRecord`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `AchievementDefinition` (`id` VARCHAR(191) NOT NULL, `key` VARCHAR(191) NOT NULL, `definitionVersion` INTEGER NOT NULL DEFAULT 1, `scope` VARCHAR(191) NOT NULL DEFAULT 'GLOBAL', `publishedVersionId` VARCHAR(191) NULL, `titleSnapshot` VARCHAR(191) NOT NULL, `descriptionSnapshot` TEXT NOT NULL, `criteria` LONGTEXT NOT NULL, `activeFrom` DATETIME(3) NULL, `inactiveAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `AchievementDefinition_key_definitionVersion_key` (`key`,`definitionVersion`), KEY `AchievementDefinition_scope_publishedVersionId_inactiveAt_idx` (`scope`,`publishedVersionId`,`inactiveAt`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `PlayerAchievement` (`id` VARCHAR(191) NOT NULL, `playerProfileId` VARCHAR(191) NOT NULL, `achievementDefinitionId` VARCHAR(191) NOT NULL, `definitionVersion` INTEGER NOT NULL, `state` VARCHAR(191) NOT NULL DEFAULT 'EARNED', `evidenceSnapshot` LONGTEXT NOT NULL, `sourceFingerprint` VARCHAR(191) NOT NULL, `earnedAt` DATETIME(3) NULL, `revokedAt` DATETIME(3) NULL, `correctedAt` DATETIME(3) NULL, `correctionReason` TEXT NULL, `showcased` BOOLEAN NOT NULL DEFAULT false, `visibility` VARCHAR(191) NOT NULL DEFAULT 'ONLY_ME', `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `PlayerAchievement_playerProfileId_achievementDefinitionId_key` (`playerProfileId`,`achievementDefinitionId`), KEY `PlayerAchievement_playerProfileId_state_earnedAt_idx` (`playerProfileId`,`state`,`earnedAt`), CONSTRAINT `PlayerAchievement_playerProfileId_fkey` FOREIGN KEY (`playerProfileId`) REFERENCES `PlayerProfile`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `PlayerAchievement_achievementDefinitionId_fkey` FOREIGN KEY (`achievementDefinitionId`) REFERENCES `AchievementDefinition`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
INSERT INTO `AchievementDefinition` (`id`,`key`,`definitionVersion`,`scope`,`titleSnapshot`,`descriptionSnapshot`,`criteria`,`createdAt`,`updatedAt`) SELECT 'wayfarer-phase4-first-artifact-v1','FIRST_PERSONAL_ARTIFACT',1,'GLOBAL','First personal artifact','Receive an authoritative personal artifact grant.','{"kind":"ARTIFACT_COUNT","minimum":1}',CURRENT_TIMESTAMP(3),CURRENT_TIMESTAMP(3) FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `AchievementDefinition` WHERE `key`='FIRST_PERSONAL_ARTIFACT' AND `definitionVersion`=1);
